import{az as e,P as t,Q as l,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const b=JSON.parse('{"title":"协调（Reconciliation）","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/协调.md","filePath":"框架/react/react/协调.md","lastUpdated":1785246304000}'),s={name:"框架/react/react/协调.md"};function o(n,a,i,c,p,d){return t(),l("div",null,[...a[0]||(a[0]=[r(`<h1 id="协调-reconciliation" tabindex="-1">协调（Reconciliation） <a class="header-anchor" href="#协调-reconciliation" aria-label="Permalink to “协调（Reconciliation）”">​</a></h1><p>协调是 React 对比新旧 UI 描述、决定如何更新的过程，也就是常说的 Diff。</p><p>目标：尽量复用已有节点，只改真正变化的部分，避免整棵树推倒重建。</p><h2 id="发生在哪一阶段" tabindex="-1">发生在哪一阶段 <a class="header-anchor" href="#发生在哪一阶段" aria-label="Permalink to “发生在哪一阶段”">​</a></h2><p>协调主要发生在 <a href="./双阶段">Render 阶段</a>：遍历 <a href="./fiber">Fiber</a>，对比新旧，打上插入 / 更新 / 删除等标记。真正改 DOM 要等到 Commit。</p><h2 id="核心启发式策略" tabindex="-1">核心启发式策略 <a class="header-anchor" href="#核心启发式策略" aria-label="Permalink to “核心启发式策略”">​</a></h2><p>React 不会做「任意两棵树的最优 Diff」（那是 O(n³) 级难题），而是用几条启发式规则把复杂度压到接近 O(n)：</p><h3 id="_1-同层级比较" tabindex="-1">1. 同层级比较 <a class="header-anchor" href="#_1-同层级比较" aria-label="Permalink to “1. 同层级比较”">​</a></h3><p>只对比同一层的节点，不跨层移动去「找同款」。</p><p>跨层变化通常被当成：旧位置删除 + 新位置创建。</p><h3 id="_2-类型不同则重建" tabindex="-1">2. 类型不同则重建 <a class="header-anchor" href="#_2-类型不同则重建" aria-label="Permalink to “2. 类型不同则重建”">​</a></h3><p>例如 <code>div</code> → <code>span</code>，或 <code>Header</code> → <code>Footer</code>：</p><ul><li>认为整棵子树都变了</li><li>销毁旧树，创建新树</li></ul><p>类型相同才会继续对比 props / 子节点，并尽量复用 Fiber / DOM。</p><h3 id="_3-用-key-识别列表项" tabindex="-1">3. 用 key 识别列表项 <a class="header-anchor" href="#_3-用-key-识别列表项" aria-label="Permalink to “3. 用 key 识别列表项”">​</a></h3><p>列表里多项同类型时，<code>key</code> 帮助 React 判断「是同一个节点换了位置」，还是「删旧建新」。</p><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span><span style="color:#BABED8;">list</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">map</span><span style="color:#F07178;">(</span><span style="color:#BABED8;font-style:italic;">item</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#F07178;"> (</span></span>
<span class="line"><span style="color:#89DDFF;">  &lt;</span><span style="color:#FFCB6B;">Item</span><span style="color:#C792EA;"> key</span><span style="color:#89DDFF;">={</span><span style="color:#BABED8;">item</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">id</span><span style="color:#89DDFF;">} </span><span style="color:#C792EA;">data</span><span style="color:#89DDFF;">={</span><span style="color:#BABED8;">item</span><span style="color:#89DDFF;">} /&gt;</span></span>
<span class="line"><span style="color:#F07178;">))</span><span style="color:#89DDFF;">}</span></span></code></pre></div><ul><li><code>key</code> 稳定且唯一 → 更容易复用，移动成本更低</li><li>用索引当 <code>key</code> 且列表会插入 / 删除 / 重排 → 容易错复用，出现状态错乱或多余更新</li></ul><h2 id="diff-时常见结果" tabindex="-1">Diff 时常见结果 <a class="header-anchor" href="#diff-时常见结果" aria-label="Permalink to “Diff 时常见结果”">​</a></h2><p>对每个节点，协调后大致会落到：</p><table tabindex="0"><thead><tr><th>结果</th><th>含义</th></tr></thead><tbody><tr><td>复用</td><td>类型与 key 对得上，更新 props 即可</td></tr><tr><td>移动</td><td>仍是同一节点，但兄弟顺序变了</td></tr><tr><td>新增</td><td>旧树没有对应节点</td></tr><tr><td>删除</td><td>新树不再需要该节点</td></tr></tbody></table><p>这些结论会以 flags 等形式记在 Fiber 上，留给 Commit 执行。</p><h2 id="和-virtual-dom、fiber-的关系" tabindex="-1">和 Virtual DOM、Fiber 的关系 <a class="header-anchor" href="#和-virtual-dom、fiber-的关系" aria-label="Permalink to “和 Virtual DOM、Fiber 的关系”">​</a></h2><ul><li>输入：<a href="./虚拟DOM">Virtual DOM / Element</a> 描述「想要的 UI」</li><li>载体：在 <a href="./fiber">Fiber</a> 树上完成对比与标记</li><li>输出：一组副作用标记 → <a href="./双阶段">Commit</a> 应用</li></ul><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>协调 = 带着启发式规则做 Diff：同层比、类型变就重建、列表靠 <code>key</code> 认亲。</p>`,26)])])}const y=e(s,[["render",o]]);export{b as __pageData,y as default};
